import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * 生效术语规则集合成器（无状态纯逻辑）。
 * 文档同时引用一个全局术语库版本和自身文档术语版本：
 * 同一 sourceTerm 与目标语言并存时文档规则整条覆盖全局规则；
 * 文档规则声明 suppressed 时对应全局规则被取消（SUPPRESSED），该术语不再参与校验。
 * 合成结果按 sourceTerm、目标语言升序稳定排序。
 */
public final class GlossaryComposer {

    /** 规则来源：GLOBAL 全局术语库；DOCUMENT 文档术语整条覆盖；SUPPRESSED 文档抑制，不参与校验。 */
    public enum Source {
        GLOBAL,
        DOCUMENT,
        SUPPRESSED
    }

    /**
     * 生效规则条目。
     *
     * @param sourceTerm          源文术语
     * @param language            目标语言码
     * @param requiredTranslation 必译文本；SUPPRESSED 时为 null
     * @param source              来源 GLOBAL/DOCUMENT/SUPPRESSED
     */
    public record EffectiveRule(String sourceTerm, String language, String requiredTranslation, Source source) {

        private static String key(String sourceTerm, String language) {
            return sourceTerm + "�" + language;
        }
    }

    private GlossaryComposer() {
    }

    /**
     * 合成生效规则集：仅保留文档目标语言内的规则，按 sourceTerm、语言升序稳定排序。
     *
     * @param globalRules      文档当前引用的全局术语版本规则（不可变快照）
     * @param documentRules    文档当前术语版本规则（不可变快照，可含 suppressed）
     * @param targetLanguages  文档目标语言集合；集合外语言的规则不进入生效集
     */
    public static List<EffectiveRule> compose(List<GlobalTermRuleRow> globalRules,
                                              List<TermRuleRow> documentRules,
                                              Set<String> targetLanguages) {
        Map<String, GlobalTermRuleRow> globalByKey = new LinkedHashMap<>();
        for (GlobalTermRuleRow rule : globalRules) {
            if (targetLanguages.contains(rule.language())) {
                globalByKey.putIfAbsent(EffectiveRule.key(rule.sourceTerm(), rule.language()), rule);
            }
        }
        Map<String, TermRuleRow> documentByKey = new LinkedHashMap<>();
        for (TermRuleRow rule : documentRules) {
            if (targetLanguages.contains(rule.language())) {
                documentByKey.putIfAbsent(EffectiveRule.key(rule.sourceTerm(), rule.language()), rule);
            }
        }
        List<EffectiveRule> effective = new ArrayList<>();
        for (Map.Entry<String, GlobalTermRuleRow> entry : globalByKey.entrySet()) {
            TermRuleRow documentRule = documentByKey.get(entry.getKey());
            if (documentRule == null) {
                GlobalTermRuleRow global = entry.getValue();
                effective.add(new EffectiveRule(global.sourceTerm(), global.language(),
                        global.requiredTranslation(), Source.GLOBAL));
            } else if (documentRule.suppressed()) {
                effective.add(new EffectiveRule(documentRule.sourceTerm(), documentRule.language(),
                        null, Source.SUPPRESSED));
            } else {
                effective.add(new EffectiveRule(documentRule.sourceTerm(), documentRule.language(),
                        documentRule.requiredTranslation(), Source.DOCUMENT));
            }
        }
        for (Map.Entry<String, TermRuleRow> entry : documentByKey.entrySet()) {
            if (globalByKey.containsKey(entry.getKey())) {
                continue;
            }
            TermRuleRow documentRule = entry.getValue();
            if (documentRule.suppressed()) {
                // 无对应全局规则的抑制条目不产生任何生效规则（无规则可取消）
                continue;
            }
            effective.add(new EffectiveRule(documentRule.sourceTerm(), documentRule.language(),
                    documentRule.requiredTranslation(), Source.DOCUMENT));
        }
        effective.sort(Comparator.comparing(EffectiveRule::sourceTerm)
                .thenComparing(EffectiveRule::language));
        return List.copyOf(effective);
    }
}

