    @Test
    @DisplayName("suppressed 入参校验：抑制规则携带 requiredTranslation 返回 400；普通规则缺必译文本返回 400")
    void suppressedValidation() throws Exception {
        long docId = createDocument(newRequestId(), "[\"en\"]", "[]");
